// @ts-nocheck -- route search types are generated by the embedded app.
//
// In-system document preview: any journal/ledger document (uploaded assignment
// files and the Azure-mirrored Aptem evidence) opens HERE — inside the system,
// with the app chrome and a Back button — never as a bare external file. PDF
// links point at this page too.
import { useQuery } from "@tanstack/react-query";
import { createFileRoute, Link, useRouter } from "@tanstack/react-router";
import { LoaderCircle } from "lucide-react";
import { getDocumentUrl, getEvidenceUrl } from "@/features/audit/learner-log-pro-hours-test/lib/manualApi";

export const Route = createFileRoute("/doc")({
  // id (a manual-row document) OR evidence (+part) — an Aptem evidence blob.
  // Numbers arrive as numbers from hand-typed / PDF URLs, strings in-app.
  validateSearch: (search: Record<string, unknown>) => ({
    id: typeof search.id === "number" ? search.id : typeof search.id === "string" ? Number(search.id) || 0 : 0,
    evidence: typeof search.evidence === "number" ? search.evidence : typeof search.evidence === "string" ? Number(search.evidence) || 0 : 0,
    part: search.part === "report" ? "report" : search.part === "original" ? "original" : "file",
  }),
  component: DocumentPreviewPage,
});

// Office formats cannot render in an iframe directly — route them through the
// Office web viewer; PDFs and images embed natively. The REAL blob path inside
// the SAS URL outranks the display name: attached docs can carry a mislabelled
// extension (e.g. a PDF assessor report named "… .docx"), and the wrong viewer
// shows "File not found".
function embedUrlOf(url: string, name: string, contentType: string | null) {
  const kind = (contentType || "").toLowerCase();
  const blobPath = url.split("?", 1)[0];
  if (/\.(pdf|png|jpe?g|gif|webp)$/i.test(blobPath)) return url;
  const isOffice = /\.(docx?|xlsx?|pptx?)$/i.test(blobPath) || /\.(docx?|xlsx?|pptx?)($|\?)/i.test(name) || kind.includes("officedocument") || kind.includes("msword") || kind.includes("ms-excel") || kind.includes("ms-powerpoint");
  return isOffice ? `https://view.officeapps.live.com/op/embed.aspx?src=${encodeURIComponent(url)}` : url;
}

function DocumentPreviewPage() {
  const router = useRouter();
  const { id, evidence, part } = Route.useSearch();
  const document = useQuery({
    queryKey: ["manual-document-url", id, evidence, part],
    queryFn: () => (evidence > 0 ? getEvidenceUrl(evidence, part) : getDocumentUrl(id)),
    enabled: id > 0 || evidence > 0,
    // SAS URLs are short-lived — refetch on a fresh visit but not per render.
    staleTime: 60_000,
  });
  const name = document.data?.name ?? "Document";

  return (
    <div className="min-h-screen bg-background">
      <header className="border-b border-border bg-surface">
        <div className="mx-auto flex max-w-[1700px] flex-wrap items-center justify-between gap-4 px-6 py-4">
          <div className="flex min-w-0 items-baseline gap-3">
            <span className="font-serif text-base text-foreground">OTJ&nbsp;Ledger</span>
            <span className="label-caps">Document preview</span>
            <span className="truncate text-sm font-medium text-foreground" title={name}>{name}</span>
          </div>
          <div className="flex items-center gap-4 text-xs text-muted-foreground">
            <button
              type="button"
              onClick={() => {
                if (window.history.length > 1) router.history.back();
                else void router.navigate({ to: "/journal" });
              }}
              className="font-medium text-foreground hover:underline"
            >
              ← Back
            </button>
            <Link to="/search" className="font-medium hover:underline">Search</Link>
            {document.data?.url ? (
              <a href={document.data.url} target="_blank" rel="noreferrer" className="font-medium text-primary hover:underline">Open in new tab ↗</a>
            ) : null}
          </div>
        </div>
      </header>

      <main className="mx-auto w-full max-w-[1700px] px-6 py-6">
        {!id && !evidence ? (
          <p className="py-16 text-center text-sm text-muted-foreground">No document was provided.</p>
        ) : document.isLoading ? (
          <p className="py-16 text-center text-sm text-muted-foreground"><LoaderCircle className="mr-2 inline h-4 w-4 animate-spin" />Preparing the document preview…</p>
        ) : document.isError ? (
          <p className="py-16 text-center text-sm text-destructive">{document.error instanceof Error ? document.error.message : "Could not load this document."}</p>
        ) : document.data?.url ? (
          <div className="overflow-hidden rounded-xl border border-border bg-card shadow-panel">
            <iframe
              src={embedUrlOf(document.data.url, document.data.name ?? "", document.data.content_type)}
              title={name}
              className="h-[84vh] w-full bg-white"
            />
          </div>
        ) : null}
      </main>
    </div>
  );
}
